// ValidateCreateRequestBody runs the validations defined on CreateRequestBody
func ValidateCreateRequestBody(body *CreateRequestBody) (err error) {
	if body.Title == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("title", "body"))
	}
	if body.SQL == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("sql", "body"))
	}
	if body.Title != nil {
		if utf8.RuneCountInString(*body.Title) < 1 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.title", *body.Title, utf8.RuneCountInString(*body.Title), 1, true))
		}
	}
	if body.Title != nil {
		if utf8.RuneCountInString(*body.Title) > 200 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.title", *body.Title, utf8.RuneCountInString(*body.Title), 200, false))
		}
	}
	if body.SQL != nil {
		err = goa.MergeErrors(err, goa.ValidatePattern("body.sql", *body.SQL, "^[^;]+$"))
	}
	if body.SQL != nil {
		if utf8.RuneCountInString(*body.SQL) < 1 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.sql", *body.SQL, utf8.RuneCountInString(*body.SQL), 1, true))
		}
	}
	if body.SQL != nil {
		if utf8.RuneCountInString(*body.SQL) > 10000 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.sql", *body.SQL, utf8.RuneCountInString(*body.SQL), 10000, false))
		}
	}
	return
}

// ValidateAddCandidateRequestBody runs the validations defined on
// add_candidate_request_body
func ValidateAddCandidateRequestBody(body *AddCandidateRequestBody) (err error) {
	if body.CandidateSQL == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("candidate_sql", "body"))
	}
	if body.CandidateSQL != nil {
		err = goa.MergeErrors(err, goa.ValidatePattern("body.candidate_sql", *body.CandidateSQL, "^[^;]+$"))
	}
	if body.CandidateSQL != nil {
		if utf8.RuneCountInString(*body.CandidateSQL) < 1 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.candidate_sql", *body.CandidateSQL, utf8.RuneCountInString(*body.CandidateSQL), 1, true))
		}
	}
	if body.CandidateSQL != nil {
		if utf8.RuneCountInString(*body.CandidateSQL) > 10000 {
			err = goa.MergeErrors(err, goa.InvalidLengthError("body.candidate_sql", *body.CandidateSQL, utf8.RuneCountInString(*body.CandidateSQL), 10000, false))
		}
	}
	return
}
